// /frontend-react/src/components/SideMenu.js (FINALIZED)

import React from 'react';

const MenuItem = ({ name, emoji, onClick, isEasyMode }) => (
    <div
        onClick={onClick}
        style={{
            display: 'flex',
            alignItems: 'center',
            padding: '25px 20px', // Spacious vertical padding
            borderBottom: '1px solid #ddd', 
            cursor: 'pointer',
            backgroundColor: 'white',
            transition: 'background-color 0.15s',
        }}
        onMouseOver={e => e.currentTarget.style.backgroundColor = '#E8F0FE'} // Soft blue hover background
        onMouseOut={e => e.currentTarget.style.backgroundColor = 'white'}
    >
        <span role="img" aria-label={name} style={{
            fontSize: isEasyMode ? '48px' : '32px', // Large emoji size
            marginRight: '20px', 
            flexShrink: 0,
        }}>{emoji}</span>
        
        <span style={{
            fontSize: isEasyMode ? '30px' : '20px', // Clear text size
            fontWeight: '900', 
            color: '#1A73E8', 
        }}>{name}</span>
    </div>
);

function SideMenu({ isEasyMode, isOpen, onClose, goToPage }) {

    if (!isOpen) {
        return null; // Don't render if not open
    }
    
    // --- Handlers (remain the same) ---
    const handleLogout = () => {
        console.log("Action: Logging out...");
        alert("Logged out successfully! Redirecting to login screen.");
        onClose();
        goToPage('dashboard'); 
    };

    const handleProfile = () => {
        console.log("Action: Viewing Profile...");
        alert("Redirecting to Profile settings.");
        onClose();
    };

    const handleLanguage = () => {
        console.log("Action: Changing Language...");
        alert("Redirecting to Language settings (e.g., Audio/Text Language).");
        onClose();
    };
    // ------------------------------------

    return (
        <div style={{
            position: 'absolute',
            top: 0,
            right: 0,
            height: '100%',
            width: '80%', 
            maxWidth: '300px', 
            backgroundColor: '#fff',
            boxShadow: '-10px 0 30px rgba(0,0,0,0.6)', 
            zIndex: 100,
            transition: 'transform 0.3s ease-out',
            transform: isOpen ? 'translateX(0)' : 'translateX(100%)',
            overflowY: 'auto',
            // --- FIX: ROUNDED CORNERS TO MATCH PHONE FRAME ---
            borderTopLeftRadius: '25px', 
            borderBottomLeftRadius: '25px',
        }}>
            {/* Header/Close Button (Flat, Clean Look) */}
            <div style={{ 
                padding: '20px 25px', 
                borderBottom: '2px solid #007bff', 
                display: 'flex', 
                justifyContent: 'space-between', 
                alignItems: 'center', 
                backgroundColor: '#1A73E8', 
                color: 'white',
                // APPLY BORDER RADIUS TO HEADER CORNERS
                borderTopLeftRadius: '25px', 
            }}>
                <h3 style={{ margin: 0, fontSize: isEasyMode ? '36px' : '24px', fontWeight: 'bold' }}>Menu</h3>
                <button 
                    onClick={onClose} 
                    style={{ 
                        background: 'none', 
                        border: 'none', 
                        color: 'white', 
                        fontSize: isEasyMode ? '36px' : '30px', 
                        cursor: 'pointer' 
                    }}
                >
                    &times;
                </button>
            </div>

            {/* Menu Items */}
            <MenuItem 
                name="Profile" 
                emoji="👤" 
                onClick={handleProfile} 
                isEasyMode={isEasyMode}
            />
            <MenuItem 
                name="Language" 
                emoji="🗣️" 
                onClick={handleLanguage} 
                isEasyMode={isEasyMode}
            />
            <MenuItem 
                name="Logout" 
                emoji="🚪" 
                onClick={handleLogout} 
                isEasyMode={isEasyMode}
            />
        </div>
    );
}

export default SideMenu;
